async function refresh(){const token=++generation;try{const s=await api('session');if(state.session?.user.id!==s.user.id)state.attendanceMonth=null;state.session=s;const requests=[api('people'),api('payroll'),api('records'),allowed('hr','finance','manager','executive')?api('dashboard'):Promise.resolve({companies:[]}),allowed()?api('accounts'):Promise.resolve({rows:[]}),allowed()?api('audit'):Promise.resolve({rows:[]}),api('configuration'),api('personnel'),api('engineering/people'),api('business/references'),api('attendance')];const [p,w,r,d,a,u,c,personnel,engineers,references,attendance]=await Promise.all(requests);if(token!==generation)return;Object.assign(state,{people:p.rows,payroll:w.rows,records:r.rows,dashboard:d.companies,executive:d.executive||null,accounts:a.rows,audit:u.rows,config:c,personnel:personnel.rows,engineers:engineers.rows,references:references.rows,attendance});if(state.company&&!s.companies.some(c=>c.code===state.company))state.company='';if(state.attendanceMonth){const {company,month}=state.attendanceMonth;state.attendanceMonth=s.companies.some(c=>c.code===company)?await api('attendance/month',{company,month}):null;if(token!==generation)return}const clean=new URL(location.href);if(clean.searchParams.has('key')){clean.searchParams.delete('key');history.replaceState(null,'',clean)}render()}catch(error){if(error.message==='LOGIN'){state.session=null;state.attendanceMonth=null;login()}else{if(state.session)flash(error.message);else $('#app').innerHTML=`<div class="login card"><h1>KYD ERP</h1><p>${esc(error.message)}</p><button data-action="reload">${L('重新連線','Reconnect','ភ្ជាប់ឡើងវិញ')}</button></div>`}}}
function languageSelect(){return `<select id="language" aria-label="Language"><option value="zh" ${lang==='zh'?'selected':''}>繁體中文</option><option value="en" ${lang==='en'?'selected':''}>English</option><option value="km" ${lang==='km'?'selected':''}>ខ្មែរ</option></select>`}
function login(){document.documentElement.lang=({zh:'zh-Hant',en:'en',km:'km'})[lang];$('#app').innerHTML=`<main class="login card"><div class="brand">KYD ERP<small>${L('雲端工作平台','Cloud workspace','ប្រព័ន្ធការងារលើអ៊ីនធឺណិត')}</small></div><h1>${t('歡迎回來')}</h1><p class="sub">${L('使用已開通的帳號登入。員工名冊匯入後，不會自動開通帳號。','Sign in with an activated account. Importing an employee does not activate access.','ចូលដោយគណនីដែលបានបើក។ ការនាំចូលបុគ្គលិកមិនបើកគណនីដោយស្វ័យប្រវត្តិទេ។')}</p><form class="form" data-form="login"><label>Email<input name="username" type="email" required autocomplete="username" maxlength="254" autocapitalize="none" spellcheck="false"></label><label>${t('密碼')}<input name="password" type="password" required autocomplete="current-password" maxlength="256"></label><div class="error" role="alert"></div><button class="primary">${t('登入')}</button></form><div class="button-row">${languageSelect()}</div></main>`}
