function moduleName(id,name,access=state.session.access){return id==='procurement'&&access?.purchaseScope==='self'?L('我的採購申請','My purchase requests','សំណើទិញរបស់ខ្ញុំ'):t(name)}
function canViewModule(id){
 if(state.session.access)return state.session.access.modules.includes(id);
 // Legacy/local fallback is deliberately conservative; the server is authoritative.
 if(allowed())return true;
 if(['home','attendance','personal','performance','training','projects','applications','settings','procurement'].includes(id))return true;
 if(id==='my-payroll')return !!state.session.user.employee_id;
 if(['people','changes'].includes(id))return allowed('hr','manager');
 if(id==='documents')return allowed('hr');
 if(['finance','payroll','vendors','pms'].includes(id))return allowed('finance');
 if(id==='approvals')return allowed('hr','manager','finance','executive');
 return false;
}
function planSummary(id){const p=hrById(id);return `<section class="card plan-summary"><div><span class="badge ${p.live?'':'amber'}">${t(p.live?'部分可用':'待建置')}</span><h2>${t('功能規劃')}</h2><p>${esc(L(p.items,p.itemsEn,p.itemsKm))}</p><small>${t('主要使用者')}：${t(p.audience)}</small></div><div><h3>${t(p.live?'目前可用':'啟用前待完成')}</h3><p>${esc(p.live?L(p.live,p.liveEn,p.liveKm):L(p.pending,p.pendingEn,p.pendingKm))}</p></div></section>`}
function plannedModule(id){const p=hrById(id);return title(p.name)+planSummary(id)+`<div class="notice info"><p>${L('此頁已依行政人事選單保留功能範圍，尚未啟用作業，不會產生正式紀錄。','This page records the agreed HR scope. Operations are not enabled and no official records are generated.','ទំព័រនេះកត់ត្រាវិសាលភាព HR។ ប្រតិបត្តិការមិនទាន់បើក និងមិនបង្កើតកំណត់ត្រាផ្លូវការ។')}</p></div><a href="${href('home')}">← ${t('返回工作首頁')}</a>`}
function myApplications(){const rows=scoped(state.records).filter(r=>r.owner===state.session.user.id&&r.kind==='leave');return title('我的申請',L('查看自己建立的人事申請，不會顯示其他人的資料。','View your own HR requests. Other employees’ requests are not shown.','មើលសំណើ HR ផ្ទាល់ខ្លួន មិនបង្ហាញសំណើរបស់អ្នកដទៃ។'))+planSummary('applications')+table(['主旨','公司','狀態','建立時間',''],rows.map(r=>`<tr><td>${esc(r.data.title)}</td><td>${companyName(r.company)}</td><td><span class="badge">${t(r.status==='draft'?'尚未送審':'作廢')}</span></td><td>${esc(new Date(r.created_at).toLocaleDateString())}</td><td>${button('查看','view-record',`data-id="${esc(r.id)}"`,false)}</td></tr>`))+`<div class="button-row"><a href="${href('personal')}">${t('假勤申請')} →</a></div>`}
function hrOverview(){return `<details class="card hr-overview"><summary>${t('行政人事功能規劃')} · 12</summary><div class="hr-plan-grid">${hrPlan.filter(p=>canViewModule(p.id)).map(p=>`<a class="plan-tile" href="${href(p.id)}"><strong>${t(p.name)}</strong><span class="badge ${p.live?'':'amber'}">${t(p.live?'部分可用':'待建置')}</span><p>${esc(L(p.items,p.itemsEn,p.itemsKm))}</p></a>`).join('')}</div></details>`}
function personalHome(){const u=state.session.user,mine=scoped(state.records).filter(r=>r.owner===u.id),drafts=mine.filter(r=>r.status==='draft');return attendanceFlowNotice()+`<section class="card personal-home"><div><h2>${L('我的工作','My work','ការងាររបស់ខ្ញុំ')}</h2><p class="sub">${L('先處理自己的申請，再進入獲授權的管理功能。','Start with your requests, then access your authorized management tools.','ចាប់ផ្តើមពីសំណើផ្ទាល់ខ្លួន រួចចូលមុខងារគ្រប់គ្រងដែលមានសិទ្ធិ។')}</p></div><div class="personal-actions"><a href="${href('applications')}">${t('我的申請')} <strong>${drafts.filter(r=>r.kind==='leave').length}</strong></a><a href="${href('attendance')}">${t('排班及考勤')} <small>${L('打卡／班表','Clock-in / shifts','ចុះម៉ោង / វេន')}</small></a>${u.employee_id?`<a href="${href('people',{detail:u.employee_id})}">${t('我的資料')} →</a><a href="${href('my-payroll')}">${t('我的薪資資料')} →</a>`:`<span class="sub">${t('管理員無員工身分')}</span>`}</div></section>`}

const modules=[...hrPlan.map(p=>[p.id,p.icon,p.name]),['finance','▤','財務管理'],['procurement','▱','採購管理'],['pms','⇄','PMS 串接'],['engineering','◇','工程與專案'],['customers','♙','客戶管理'],['vendors','▱','供應商資料'],['files','▧','文件管理'],['approvals','✓','申請與簽核'],['overview','▦','營運總覽'],['my-payroll','▤','我的薪資資料']];
function title(text,description='',action=''){return `<div class="heading"><div><h1>${esc(t(text))}</h1><div class="sub">${esc(t(description))}</div></div>${action}</div>`}
function empty(text='尚無紀錄',description='',action=''){return `<div class="card empty"><div class="empty-icon">▱</div><h2>${esc(t(text))}</h2><p>${esc(t(description))}</p>${action}</div>`}
function button(label,action,extra='',primary=true){return `<button class="${primary?'primary':''}" data-action="${action}" ${extra}>${esc(t(label))}</button>`}
function stats(items){return `<div class="stats">${items.map(([label,value,sub=''])=>`<div class="stat"><div class="label">${esc(t(label))}</div><div class="value">${value}</div><small>${esc(t(sub))}</small></div>`).join('')}</div>`}
function table(head,rows){return `<div class="card flush"><div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${esc(t(h))}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${head.length}"><div class="empty">${t('找不到資料')}</div></td></tr>`}</tbody></table></div></div>`}
function render(){if(!state.session)return login();document.documentElement.lang=({zh:'zh-Hant',en:'en',km:'km'})[lang];let r=route(),view=r.view||'home';if(view==='approval')view='approvals';if(view==='project')view='engineering';if(view==='suppliers')view='procurement';if(!modules.some(m=>m[0]===view))view='home';const user=state.session.user;if(r.company&&state.session.companies.some(c=>c.code===r.company))state.company=r.company;
 const selfProfile=view==='people'&&r.detail&&r.detail===user.employee_id;
 const views={engineering,customers:()=>businessParty('customer'),vendors:()=>businessParty('supplier'),files,approvals,overview:()=>executiveReady()?(route().tab?executiveDetail():executiveHome()):businessOverview(),home,people,finance,procurement:()=>records('purchase'),projects:()=>planSummary('projects')+records('task'),personal,documents,pms,settings,attendance,performance:()=>plannedModule('performance'),changes:()=>plannedModule('changes'),training:()=>plannedModule('training'),payroll:()=>title('薪酬與社保')+planSummary('payroll')+payroll(),applications:myApplications,'my-payroll':()=>{const saved=state.payroll;try{state.payroll=saved.filter(p=>p.id===user.employee_id);return title('我的薪資資料')+payroll()}finally{state.payroll=saved}}};
 const content=canViewModule(view)||selfProfile?views[view]():title(modules.find(m=>m[0]===view)[2])+empty(L('未授權此功能','Access not granted','មិនមានសិទ្ធិចូលមុខងារនេះ'),L('此功能需個別授權。','This function requires separate authorization.','មុខងារនេះត្រូវការសិទ្ធិដាច់ដោយឡែក។'));
 const navGroup=(label,list)=>!list.some(([key])=>canViewModule(key))?'':`<details class="nav-group" ${list.some(m=>m[0]===view)?'open':''}><summary class="nav-label">${t(label)}</summary>${list.filter(([key])=>canViewModule(key)).map(([key,icon,label])=>`<a href="${href(key)}" class="${key===view?'active':''}" ${key===view?'aria-current="page"':''}><span class="ico" aria-hidden="true">${icon}</span><span>${moduleName(key,label)}</span>${hrById(key)&&!hrById(key).live?'<i class="planned-dot" aria-label="'+t('待建置')+'"></i>':''}</a>`).join('')}</details>`;const name=user.role==='owner'?L('系統管理員（你）','Administrator (you)','អ្នកគ្រប់គ្រងប្រព័ន្ធ (អ្នក)'):user.display_name;$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">KYD ERP<small>WORKSPACE</small></div><nav class="nav" aria-label="${t('工作首頁')}">${navGroup('行政人事',modules.slice(0,12))}${navGroup('企業業務',modules.slice(12).filter(m=>m[0]!=='my-payroll'))}</nav><div class="sidebar-foot"><strong>${L('雲端工作平台','Cloud workspace','ប្រព័ន្ធការងារលើអ៊ីនធឺណិត')}</strong>${L('依帳號與公司授權使用','Account and company scoped access','ចូលតាមសិទ្ធិគណនី និងក្រុមហ៊ុន')}</div></aside><div class="main"><header class="topbar"><div class="left"><span class="mobile-brand">KYD</span><span class="small-label">${t('歸屬公司')}</span><select id="company" aria-label="${t('歸屬公司')}"><option value="">${t('全部公司')}</option>${state.session.companies.map(c=>`<option value="${esc(c.code)}" ${state.company===c.code?'selected':''}>${esc(companyName(c.code))}</option>`).join('')}</select></div><div class="right">${languageSelect()}<div class="account-chip"><div class="avatar">${esc(name.slice(0,1))}</div><div>${esc(name)}<small>${executiveLabel(user,state.session.access)}</small></div></div><button class="quiet" data-action="logout">${t('登出')}</button></div></header><nav class="mobile-module-nav"><label>${t('功能選單')}<select id="module" aria-label="${t('功能選單')}">${[['行政人事',modules.slice(0,12)],['企業業務',modules.slice(12).filter(m=>m[0]!=='my-payroll')]].filter(([,items])=>items.some(([key])=>canViewModule(key))).map(([label,items])=>`<optgroup label="${t(label)}">${items.filter(([key])=>canViewModule(key)).map(([key,icon,label])=>`<option value="${key}" ${key===view?'selected':''}>${moduleName(key,label)}</option>`).join('')}</optgroup>`).join('')}</select></label></nav><main class="content"><div class="crumb">KYD ERP / ${t(hrById(view)?'行政人事':'企業業務')} / ${moduleName(view,modules.find(m=>m[0]===view)[2])}</div>${state.session.needsPassword?`<div class="notice"><div><strong>${t('建立自己的登入密碼')}</strong><p>${t('請先設定密碼，再開始修改資料或開通員工帳號。')}</p></div>${button('設定密碼','password')}</div>`:''}${executiveReady()&&r.from==='dashboard'&&view!=='home'?executiveBack():''}${content}</main></div></div>`}
function home(){if(executiveReady())return executiveHome();const rows=scoped(state.dashboard),active=rows.reduce((s,r)=>s+r.active,0),departed=rows.reduce((s,r)=>s+r.departed,0),drafts=scoped(state.records).filter(r=>r.status==='draft').length;return title('工作首頁','目前只顯示實際匯入與已保存的資料。')+personalHome()+stats([['在職員工',state.dashboard.length?active:state.people.filter(p=>p.status==='在職').length],['離職紀錄',departed],['已授權公司',state.company?1:state.session.companies.length],['已存草稿',drafts]])+`<div class="grid"><section class="card"><h2>${t('公司人員概況')}</h2>${rows.length?rows.map(c=>`<a class="company-row" ${canViewModule('people')?`href="${href('people',{company:c.code})}"`:''}><div><strong>${esc(companyName(c.code))}</strong><small>${esc(state.session.companies.find(x=>x.code===c.code)?.name)}<br>${c.total?`${t('離職')} ${c.departed} · ${t('部門')} ${c.departments}`:L('名冊未提供員工資料','No employees supplied in roster','បញ្ជីមិនបានផ្តល់ទិន្នន័យបុគ្គលិក')}</small></div><div class="number">${c.total?c.active:'—'}<small>${c.total?t('在職'):t('未提供')}</small></div></a>`).join(''):`<p class="muted">${t('所有資料按授權公司顯示。')}</p>`}</section><section class="card"><h2>${t('常用工作')}</h2>${[['people','員工與組織','查看員工與任職資料'],['payroll','薪酬與社保','按公司核對薪資資料'],['procurement','採購管理','建立採購申請'],['settings','報表與設定','管理登入與使用權限']].filter(([v])=>canViewModule(v)).map(([v,h,s])=>`<a class="link-row" href="${href(v)}"><span><strong>${moduleName(v,h)}</strong><small>${t(s)}</small></span><span>→</span></a>`).join('')}</section></div><div class="footnote">${L('財務營收、收付款與經營 KPI 會從後續建立的正式業務資料計算；目前未填入數字。','Revenue, payments and business KPIs require actual business records and are not populated yet.','ចំណូល ការទូទាត់ និង KPI នឹងគណនាពីទិន្នន័យអាជីវកម្មពិត ដែលមិនទាន់មាននៅឡើយ។')}</div>`+hrOverview()}
function people(){const r=route();if(r.detail){const p=state.people.find(p=>p.id===r.detail);if(p)return person(p);return title('員工與組織')+empty('找不到資料',L('此員工不在你的授權範圍，或編號不存在。','This employee is outside your access or does not exist.','បុគ្គលិកនេះនៅក្រៅសិទ្ធិរបស់អ្នក ឬមិនមាន។'),`<a href="${href('people')}">${t('返回員工清單')}</a>`)}let rows=scoped(state.people).filter(p=>(!Object.hasOwn(r,'department')||(p.department||'')===r.department)&&(!(r.status||state.status)||p.status===(r.status||state.status))&&(!state.search||[p.id,p.displayName,p.englishName,p.department].some(v=>String(v).toLowerCase().includes(state.search.toLowerCase()))));return title('員工與組織','任職公司與支援項目分開管理。')+`<div class="toolbar"><input id="search" type="search" value="${esc(state.search)}" placeholder="${t('搜尋姓名、編號、部門')}" aria-label="${t('搜尋姓名、編號、部門')}"><select id="status" aria-label="${t('狀態')}"><option value="">${t('所有狀態')}</option>${['在職','已離職'].map(s=>`<option value="${s}" ${s===(r.status||state.status)?'selected':''}>${t(s)}</option>`).join('')}</select>${Object.hasOwn(r,'department')?`<a class="badge" href="${executiveReady()?executiveLink('people'):href('people')}">${esc(r.department||t('未提供'))} ×</a>`:''}<span class="count">${rows.length} ${t('筆資料')}</span></div>`+table(['員工','公司','部門','職務','支援項目','狀態',''],rows.map(p=>`<tr><td><a class="name" href="${href('people',{...route(),detail:p.id})}">${esc(p.displayName)}</a><small>${esc(personId(p))}</small></td><td>${esc(companyName(p.companyCode))}</td><td>${esc(p.department||t('未提供'))}</td><td class="ellipsis">${esc(p.position||t('未提供'))}</td><td>${esc(p.serviceProjects?.join(' / ')||t('待設定'))}</td><td><span class="badge ${p.status==='在職'?'green':''}">${t(p.status)}</span></td><td><a href="${href('people',{...route(),detail:p.id})}">${t('查看')} →</a></td></tr>`))+sourceFoot()}
function sourceFoot(){return `<div class="footnote source">${t('原始資料來源')}：${esc(state.session.source.source.split('/').pop())} · ${esc(state.session.source.asOf)}<br>${L('個別新增與修改以員工詳細頁和操作紀錄為準。','Individual additions and changes are recorded in employee details and the activity log.','ការបន្ថែម និងការកែប្រែត្រូវបានកត់ត្រាក្នុងព័ត៌មានបុគ្គលិក និងកំណត់ត្រាសកម្មភាព។')}</div>`}
function person(p){const back={...route()};delete back.detail;const manager=state.people.find(x=>x.id===p.managerId);const data=[['員工編號',p.employeeNumber===null?t('未提供'):(p.employeeNumber||p.id)],['薪資歸屬',companyName(p.companyCode)],['姓名',p.nativeName||p.displayName],['英文姓名',p.englishName],['Email',p.email],['部門',p.department],['職務',p.position],['到職日期',p.joined],['離職日期',p.resigned],['直屬主管',manager?.displayName||p.managerId||t('待設定')],['支援項目',p.serviceProjects?.join(' / ')||t('待設定')]];return `<div class="toolbar"><a href="${href('people',back)}">← ${t('返回員工清單')}</a></div>`+title(p.displayName,`${personId(p)} · ${companyName(p.companyCode)}`,allowed('hr')?button('編輯任職資料','edit-person',`data-id="${esc(p.id)}"`):'')+`<section class="card"><div class="card-title"><h2>${t('員工與組織')}</h2><span class="badge ${p.status==='在職'?'green':''}">${t(p.status)}</span></div><dl class="details">${data.map(([label,v])=>`<div><dt>${t(label)}</dt><dd>${esc(v||t('未提供'))}</dd></div>`).join('')}</dl></section><div class="notice info"><p>${t('不改變任職公司與薪資歸屬。')} ${L('共享團隊可以支援不同項目；支援項目不代表由該項目的公司發薪。','Shared staff may support different projects without changing their payroll employer.','បុគ្គលិកអាចគាំទ្រគម្រោងផ្សេងៗ ដោយមិនផ្លាស់ប្តូរក្រុមហ៊ុនបើកប្រាក់ខែ។')}</p></div>${p.sourceType||p.sourceSheet?`<div class="footnote">${t('原始資料來源')}：${p.sourceType==='user_instruction'?L('使用者指示新增 · 2026-10-27','Added on user instruction · 2026-10-27','បានបន្ថែមតាមការណែនាំរបស់អ្នកប្រើ · 2026-10-27'):`${esc(p.sourceSheet)} · ${L('第','Row','ជួរទី')} ${p.sourceRow} ${L('列','','')}`} · ${L('版本','Revision','កំណែ')} ${p.revision}</div>`:''}`}
function finance(){
 if(route().tab==='payroll')return canViewModule('payroll')?title('薪酬與社保')+planSummary('payroll')+payroll():title('我的薪資資料')+payroll();
 const tab=route().tab||'receivable';
 const tabs=[['receivable','應收款'],['payable','應付款'],['settlement','業主結算'],['rules','項目收費規則']];
 return title('財務管理','先選公司，再核對人員與金額。')+`<nav class="tabs">${tabs.filter(([v])=>!['settlement','rules'].includes(v)||allowed('finance')).map(([v,l])=>`<a href="${href('finance',{tab:v})}" class="${tab===v?'active':''}">${t(l)}</a>`).join('')}</nav>`+(tab==='payroll'?payroll():tab==='rules'?(allowed('finance')?billingRules():empty('找不到資料')):records(['receivable','payable','settlement'].includes(tab)?tab:'receivable',false));
}
function payroll(){const rows=scoped(state.payroll).filter(p=>p.status==='在職'),sum=rows.reduce((s,p)=>s+(p.basicSalary??0),0),missing=rows.filter(p=>p.basicSalary===null).length;return stats([['在職員工',rows.length],['已知基本薪資合計',money(sum)],['基本薪資待補',missing],['薪資公司數',new Set(rows.map(p=>p.companyCode)).size]])+`<div class="notice info"><p>${t('這是名冊中的薪資基礎資料，尚未計算考勤、扣款、稅金與實發薪資。')} ${t('服務費獨立列示，尚未併入計薪。')}</p></div>`+table(['員工','薪資歸屬','職務','基本薪資','津貼','服務費'],rows.map(p=>`<tr><td><strong>${esc(p.displayName)}</strong><small>${esc(personId(p))}</small></td><td>${esc(companyName(p.companyCode))}</td><td class="ellipsis">${esc(p.position||t('未提供'))}</td><td class="money">${money(p.basicSalary)}</td><td class="money">${money(p.allowance)}</td><td class="money">${money(p.serviceCharge)}</td></tr>`))+sourceFoot()}
const kindLabel={purchase:'採購管理',receivable:'應收款',payable:'應付款',settlement:'業主結算',task:'專案交辦',leave:'假勤申請'};
function canCreate(kind){if(state.session.access)return state.session.access.createKinds.includes(kind);if(businessTypes.includes(kind))return allowed()||kind==='supplier'&&allowed('finance');return ({purchase:allowed('employee','manager','finance','hr','executive'),receivable:allowed('finance'),payable:allowed('finance'),settlement:allowed('finance'),task:allowed('manager','hr','executive'),leave:!!state.session.user.employee_id&&allowed('employee','manager','finance','hr','executive')})[kind]}
function records(kind,heading=true){const rows=scoped(state.records).filter(r=>r.kind===kind);const description=['leave','task'].includes(kind)?L('儲存為草稿；尚未送審、指派或核准。','Saved as drafts; not submitted, assigned or approved.','រក្សាជាសេចក្តីព្រាង មិនទាន់ដាក់ស្នើ ចាត់តាំង ឬអនុម័ត។'):'從真實單據開始建立，尚未入帳或付款。';const create=canCreate(kind)?button('新增草稿','new-record',`data-kind="${kind}"`):'';return (heading?title(kind==='purchase'?moduleName('procurement',kindLabel[kind]):kindLabel[kind],description,create):`<div class="toolbar"><p class="sub">${t(description)}</p><span class="count">${create}</span></div>`)+(rows.length?table(['主旨','公司',...(['leave','task'].includes(kind)?[]:['往來對象','金額']),'狀態','建立時間',''],rows.map(r=>`<tr><td><strong>${esc(r.data.title)}</strong><small>${esc(r.id)}</small></td><td>${esc(companyName(r.company))}<small>${esc(state.config.projects?.find(p=>p.id===r.data.project)?.name||'')}</small></td>${['leave','task'].includes(kind)?'':`<td>${esc(r.data.party||'—')}</td><td class="money">${r.data.amountCents!==undefined?money(r.data.amountCents/100):'—'}</td>`}<td><span class="badge ${r.status==='draft'?'amber':''}">${t(r.status==='draft'?'草稿':'作廢')}</span>${r.data.receiptReview==='pending'?`<small class="review-needed">${t('轉帳待核對')}</small>`:''}</td><td>${esc(new Date(r.created_at).toLocaleDateString())}</td><td>${button('查看','view-record',`data-id="${esc(r.id)}"`,false)}</td></tr>`)):empty('尚無紀錄',L('這裡會顯示實際建立的資料。現有名冊沒有提供這類單據。','Actual records will appear here. These documents were not supplied in the roster.','ទិន្នន័យពិតនឹងបង្ហាញទីនេះ។ បញ្ជីបុគ្គលិកមិនមានឯកសារប្រភេទនេះទេ។'),create))}
function personal(){return planSummary('personal')+records('leave')}
function documents(){const rows=scoped(state.people).filter(p=>p.documents);return planSummary('documents')+title('證件與合約',L('名冊中的文件備註，並非已上傳的文件檔案。','Document status from the roster; no files have been uploaded.','ស្ថានភាពឯកសារពីបញ្ជី មិនមែនឯកសារដែលបានផ្ទុកឡើង។'))+table(['員工','公司',L('合約','Contract','កិច្ចសន្យា'),L('履歷','CV','ប្រវត្តិរូប'),L('保密協議','Confidentiality','កិច្ចព្រមព្រៀងសម្ងាត់')],rows.map(p=>`<tr><td>${esc(p.displayName)}<small>${esc(personId(p))}</small></td><td>${esc(companyName(p.companyCode))}</td>${['employmentContract','cv','confidentiality'].map(k=>`<td><span class="badge ${p.documents[k]?'green':''}">${t(p.documents[k]?'已確認有資料':'待核對')}</span></td>`).join('')}</tr>`))+sourceFoot()}
function pms(){
 const cfg=state.config;
 return title('PMS 串接',L('物業、租約、維修與客訴由 PMS 處理。','Properties, leases, maintenance and complaints are handled in PMS.','អចលនទ្រព្យ កិច្ចសន្យាជួល ការថែទាំ និងបណ្តឹងត្រូវបានដោះស្រាយក្នុង PMS។'))+`<div class="notice info"><p>${t('以下已依客戶回覆設定。PMS 資料同步尚未連線。')}</p></div><div class="grid">${availableProjects().map(p=>`<section class="card"><span class="badge">${t(p.type==='office'?'商辦':'公寓')}</span><h1>${esc(p.name)}</h1><h3>${t('出帳公司')} · ${esc(companyName(p.company))}</h3><p class="sub">${t(p.shortStay?'部分房源提供短租':'目前不提供短租')}</p>${p.meetingCenter?`<details><summary>${t('會議中心')}</summary><p>${t(p.meetingCenter.monthlyPointsRule)}<br>${t('加購：每點 USD 2；亦提供外部客戶租用。')}</p><p class="sub">${t('免費點數的幣別、尾數及有效期待確認，尚未自動計算。')}</p></details>`:''}${p.futurePlans?.length?`<p class="sub">${t('23 樓共享辦公室短租：僅為未來考慮。')}</p>`:''}<span class="badge amber">${t('尚未連線')}</span></section>`).join('')}</div>${allowed('hr','manager','finance','executive')?`<section class="card section-gap"><h2>${t('清潔排班依據')}</h2><p class="sub">${t('已記錄頻率；詳細排班待提供，尚未產生工作單。')}</p>${(cfg.housekeeping||[]).map(h=>`<div class="rule-row"><strong>${t(h.category)}</strong><span>${t(h.frequency)}</span></div>`).join('')}</section><section class="card section-gap"><h2>${t('待確認事項')}</h2><ul class="rule-list">${(cfg.pending||[]).map(v=>`<li>${esc(t(v))}</li>`).join('')}</ul></section>`:''}${configSource()}`;
}
function settings(){const user=state.session.user;let html=planSummary('settings')+title('報表與設定','管理登入與使用權限',button(state.session.needsPassword?'設定密碼':'修改密碼','password'))+`<div class="card"><h2>${t('帳號')} · ${esc(user.email||user.id)}</h2><p class="sub">${roleName(user.role)} · ${t('所有資料按授權公司顯示。')}</p></div>`;if(!allowed())return html;html+=`<div class="card-title section-gap"><h2>${L('已開通帳號','Activated accounts','គណនីដែលបានបើក')}</h2>${button('新增帳號','new-account')}</div>`+table(['姓名','帳號','權限角色','公司範圍','狀態',''],state.accounts.map(a=>`<tr><td>${esc(a.display_name)}</td><td>${esc(a.email||t('待設定'))}</td><td>${executiveLabel(a,a.access)}</td><td>${a.role==='owner'?t('全部公司'):esc(a.scopes.map(companyName).join(' / '))}</td><td><span class="badge ${a.enabled?'green':''}">${t(a.enabled?'啟用':'已停用')}</span></td><td>${button(L('查看權限','View access','មើលសិទ្ធិ'),'account-access',`data-id="${esc(a.id)}"`,false)} ${a.role==='owner'?'':button(a.enabled?'停用':'重新啟用','account-toggle',`data-id="${esc(a.id)}" data-enable="${a.enabled?'0':'1'}"`,false)}</td></tr>`))+`<h2 class="section-gap">${t('操作紀錄')}</h2>`+table(['建立時間','操作者','操作','對象'],state.audit.map(a=>`<tr><td>${esc(new Date(a.at).toLocaleString())}</td><td>${esc(a.actor)}</td><td class="audit-action">${esc(a.action)}</td><td>${esc(a.resource)}</td></tr>`));return html}
function modal(label,inner){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${esc(t(label))}</h2><button class="quiet" data-action="close" aria-label="${t('關閉')}">×</button></div>${inner}`;d.showModal();enhanceForm(d.querySelector('form'))}
const formEnd = ()=>`<div class="error" role="alert"></div><div class="button-row"><button type="button" data-action="close">${t('取消')}</button><button class="primary">${t('儲存')}</button></div></form>`;
const input = (label,name,value='',attrs='')=>`<label>${t(label)}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;
function writeReady(){if(state.session.needsPassword){flash(t('請先設定密碼，再開始修改資料或開通員工帳號。'));passwordForm();return false}return true}
function passwordForm(){const username=state.session.user.email||state.session.user.id;modal(state.session.needsPassword?'設定密碼':'修改密碼',`<form class="form" data-form="password">${!state.session.needsPassword?input('目前密碼','currentPassword','','type="password" required autocomplete="current-password"'):''}${input('新密碼','password','','type="password" required minlength="12" maxlength="256" autocomplete="new-password"')}${input('再次輸入新密碼','confirm','','type="password" required minlength="12" autocomplete="new-password"')}<div class="help">${L('使用至少 12 個字元。帳號為 ${esc(username)}。密碼由你自行設定，不會放在網頁或名冊中。','Use at least 12 characters. Your username is ${esc(username)}. Choose your own password.','ប្រើយ៉ាងតិច ១២ តួអក្សរ។ ឈ្មោះគណនីគឺ ${esc(username)}។ សូមកំណត់ពាក្យសម្ងាត់ដោយខ្លួនឯង។').replace('${esc(username)}',esc(username))}</div>${formEnd()}`)}
function personForm(id){if(!writeReady())return;const p=state.people.find(x=>x.id===id);if(!p)return;modal('編輯任職資料',`<form class="form" data-form="person" data-id="${esc(p.id)}" data-revision="${p.revision}"><p>${esc(p.displayName)} · ${esc(companyName(p.companyCode))}</p>${input('部門','department',p.department,'required maxlength="100"')}${input('職務','position',p.position,'required maxlength="100"')}${personnelPicker('直屬主管','managerId','manager',p.managerId||'',p.id)}<fieldset><legend>${t('支援項目')}</legend>${['KY iCenter','Golden One'].map(v=>`<label class="check"><input type="checkbox" name="serviceProjects" value="${v}" ${p.serviceProjects?.includes(v)?'checked':''}>${v}</label>`).join('')}</fieldset><div class="help">${t('不改變任職公司與薪資歸屬。')}</div>${formEnd()}`)}
function recordForm(kind,existing=null){
 if(!writeReady())return;
 const data={...(existing?.data||{})};let companies=state.session.companies;const context=bRecord(route().detail);if(!existing&&['purchase','payable'].includes(kind)){if(context?.kind==='engineering')data.engineeringId=context.id;if(context?.kind==='supplier'){data.supplierId=context.id;data.party=context.data.title}}
 if(kind==='leave')companies=companies.filter(c=>c.code===state.people.find(p=>p.id===state.session.user.employee_id)?.companyCode);
 const projectFields=['receivable','settlement'].includes(kind);
 modal(kindLabel[kind],`<form class="form" data-form="record" data-kind="${kind}" ${existing?`data-id="${esc(existing.id)}" data-revision="${existing.revision}"`:''}>
 ${projectFields?selectField('項目','project',availableProjects().map(p=>[p.id,p.name]),data.project,kind==='settlement',kind!=='settlement'?'一般業務（不屬物業項目）':'請選擇'):''}
 <label>${t('歸屬公司')}<select name="company" required ${existing?'disabled':''}><option value="">${t('歸屬公司')}</option>${companies.map(c=>`<option value="${c.code}" ${(existing?.company||bRecord(data.engineeringId||data.supplierId)?.company||state.company)===c.code?'selected':''}>${esc(companyName(c.code))}</option>`).join('')}</select></label>
 ${projectFields?`<div class="help" data-company-note>${t('項目決定出帳公司；不改變員工的薪資歸屬。')}</div>`:''}
 ${['purchase','payable'].includes(kind)?bFinanceFields(data):''}
 ${input('主旨','title',data.title,'required maxlength="160"')}
 ${recordPersonnelFields(kind,data)}
 ${['purchase','receivable','payable','settlement'].includes(kind)?input(kind==='settlement'?'業主姓名':'往來對象','party',data.party,'required maxlength="160"'):''}
 ${kind==='receivable'?'<div class="form" data-billing-fields></div>':''}
 ${['purchase','receivable','payable'].includes(kind)?input('金額','amount',data.amountCents!==undefined?data.amountCents/100:'','type="number" min="0.01" step="0.01" max="1000000000" required')+'<div class="help">USD</div>':''}
 ${['leave','settlement'].includes(kind)?input('起始日期','start',data.start,'type="date" required')+input('結束日期','end',data.end,'type="date" required'):''}
 ${kind==='settlement'?selectField('結算週期','frequency',(state.config.settlement?.frequencies||[]).map(v=>[v,optionLabel(v)]),data.frequency,true)+selectField('結算單語言','statementLanguage',[['zh','繁體中文'],['en','English'],['km','ខ្មែរ']],data.statementLanguage,true)+selectField('撥款方式','payoutMethod',(state.config.settlement?.payoutMethods||[]).map(v=>[v,optionLabel(v)]),data.payoutMethod,true)+`<div class="help">${t('結算幣別：USD。先建立結算資料；尚未計算扣款、扣繳稅或實際撥款。')}</div>`:''}
 <label>${t('備註')}<textarea name="notes" maxlength="2000">${esc(data.notes)}</textarea></label><div class="help">${t('此階段儲存為草稿。簽核流程尚未啟用，不會自動送審、入帳或付款。')}</div>${formEnd()}`);
 if(projectFields)syncBillingFields(data);if(['purchase','payable'].includes(kind))syncFinanceCompany($('#dialog form'));
}
function recordView(id){
 const r=state.records.find(r=>r.id===id);if(!r)return;if(businessTypes.includes(r.kind))return businessView(id);
 const mutable=r.status==='draft'&&(r.owner===state.session.user.id||allowed());
 const labels={handlerId:personnelLabel(({receivable:'finance',payable:'finance',settlement:'finance',purchase:'procurement',task:'hr'})[r.kind]||'hr'),engineeringId:'關聯工程',supplierId:'關聯供應商',notes:'備註',amountCents:'金額',currency:'幣別',party:'往來對象',start:'起始日期',end:'結束日期',employeeId:'員工編號',project:'項目',counterpartyType:'收費對象',feeItem:'收費項目',paymentMethod:'收款方式',frequency:'結算週期',statementLanguage:'結算單語言',payoutMethod:'撥款方式',configVersion:'規則版本',expectedAccount:'應收帳戶備註',actualAccount:'實際入帳帳戶備註',actualReceivingCompany:'實際收款公司',wrongAccount:'轉錯帳戶',receiptReview:'收款核對',reconciliationNote:'收款核對備註',taxStatus:'稅務核對'};
 const display=(k,v)=>k==='handlerId'?esc(bPerson(v,r.data.handlerName)):k==='amountCents'?money(v/100):esc(['engineeringId','supplierId'].includes(k)?bRecord(v)?.data.title||state.references?.find(r=>r.id===v)?.title||v:k==='project'?state.config.projects.find(p=>p.id===v)?.name||v:k==='actualReceivingCompany'?companyName(v):k==='wrongAccount'?(v?t('是'):t('否')):k==='statementLanguage'?({zh:'繁體中文',en:'English',km:'ខ្មែរ'})[v]:optionLabel(v));
 modal(r.data.title,`<dl class="details"><div><dt>${t('公司')}</dt><dd>${esc(companyName(r.company))}</dd></div><div><dt>${t('狀態')}</dt><dd>${t(r.status==='draft'?'草稿':'作廢')}</dd></div>${Object.entries(r.data).filter(([k,v])=>!['title','assignmentSource','handlerName'].includes(k)&&v!==''&&!(k==='currency'&&r.data.amountCents!==undefined)&&!(k==='party'&&r.data.supplierId&&bRecord(r.data.supplierId)?.data.title===v)).map(([k,v])=>`<div class="${k==='notes'?'full':''}"><dt>${t(labels[k]||k)}</dt><dd>${display(k,v)}</dd></div>`).join('')}</dl><div class="button-row">${mutable?button('作廢','void-record',`data-id="${esc(r.id)}"`,false)+button(L('編輯草稿','Edit draft','កែសេចក្តីព្រាង'),'edit-record',`data-id="${esc(r.id)}"`):''}${button('關閉','close','',false)}</div>`);
}
function accountForm(){if(!writeReady())return;const people=state.people.filter(p=>p.status==='在職'&&!state.accounts.some(a=>a.employee_id===p.id));modal('新增帳號',`<form class="form" data-form="account"><label>${t('員工')}<select name="employeeId" required><option value="">${t('員工')}</option>${people.map(p=>`<option value="${esc(p.id)}">${esc(p.id)} · ${esc(p.displayName)} · ${companyName(p.companyCode)}</option>`).join('')}</select></label><label>${t('權限角色')}<select name="role">${['employee','hr','finance','manager','executive'].map(r=>`<option value="${r}">${roleName(r)}</option>`).join('')}</select></label><div class="help">${L('員工：本人資料；人資：授權公司人事資料；財務：授權公司薪資及收付款；主管：授權公司員工基本資料；經營主管：管理總覽與員工基本資料。人資／主管／經營主管不會取得他人薪資。','Employee: self only. HR: company HR files. Finance: company payroll and finance. Manager: company basic profiles. Executive: management overview and basic employee profiles. HR, managers and executives cannot see others’ salary.','បុគ្គលិក៖ ទិន្នន័យផ្ទាល់ខ្លួន។ HR៖ ឯកសារបុគ្គលិកក្រុមហ៊ុន។ ហិរញ្ញវត្ថុ៖ ប្រាក់ខែ និងការទូទាត់។ អ្នកគ្រប់គ្រង៖ ព័ត៌មានមូលដ្ឋាន។ ថ្នាក់ដឹកនាំ៖ ទិដ្ឋភាពក្រុមហ៊ុន។ HR និងអ្នកគ្រប់គ្រងមិនឃើញប្រាក់ខែអ្នកផ្សេងទេ។')}</div><fieldset><legend>${t('公司範圍')}</legend>${state.session.companies.map(c=>`<label class="check"><input type="checkbox" name="scopes" value="${c.code}">${esc(companyName(c.code))}</label>`).join('')}</fieldset><div class="help">${L('一般員工只開通本人任職公司；其他角色請逐一勾選公司。帳號使用 email。','Employees are limited to their employer. For other roles, explicitly select companies. Sign in with email.','បុគ្គលិកធម្មតាចូលបានតែក្រុមហ៊ុននិយោជក។ តួនាទីផ្សេងត្រូវជ្រើសក្រុមហ៊ុន។ ចូលប្រើដោយអ៊ីមែល។')}</div>${input('Email','email','','type="email" maxlength="254" required autocomplete="email" autocapitalize="none"')}${input('密碼','password','','type="password" minlength="12" maxlength="256" required autocomplete="new-password"')}${formEnd()}`)}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;try{switch(b.dataset.action){case'business-form':if($('#dialog').open)$('#dialog').close();businessForm(b.dataset.kind,b.dataset.parent,b.dataset.id);break;case'business-view':businessView(b.dataset.id);break;case'close':$('#dialog').close();break;case'reload':await refresh();break;case'logout':await api('logout',{});state={...state,session:null,people:[],payroll:[],records:[],accounts:[],audit:[],dashboard:[],executive:null,attendance:null,attendanceMonth:null};login();break;case'password':passwordForm();break;case'edit-person':personForm(b.dataset.id);break;case'new-record':recordForm(b.dataset.kind);break;case'view-record':recordView(b.dataset.id);break;case'edit-record':{const r=state.records.find(r=>r.id===b.dataset.id);$('#dialog').close();recordForm(r.kind,r);break}case'void-record':{const r=state.records.find(r=>r.id===b.dataset.id);if(!writeReady())break;await api('records/void',{id:r.id,revision:r.revision});$('#dialog').close();await refresh();flash(t('儲存成功'));break}case'new-account':accountForm();break;case'account-access':accountAccess(b.dataset.id);break;case'account-toggle':if(writeReady()){await api('accounts/toggle',{id:b.dataset.id,enabled:b.dataset.enable==='1'});await refresh();flash(t('儲存成功'))}break}}catch(error){flash(error.message)}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='module'){go(el.value);return}if(el.name==='company'&&el.closest('[data-form=business]'))syncBusinessCompany(el.form);if(el.name==='company'&&el.closest('[data-form=record]'))syncFinanceCompany(el.form);if(el.name==='employeeId'&&el.closest('[data-form=account]')){const p=state.people.find(p=>p.id===el.value);el.form.elements.email.value=p?.email||''}if(el.name==='project'&&el.closest('[data-form=record]'))syncBillingFields();if(el.name==='counterpartyType'&&el.closest('[data-form=record]'))syncFeeOptions();if(el.id==='language'){lang=el.value;localStorage.setItem('kyd_ui_locale_v1',lang);state.session?render():login()}if(el.id==='company'){state.company=el.value;state.search='';state.status='';const r=route();for(const k of ['detail','company','department','filter','status'])delete r[k];if(el.value)r.company=el.value;location.hash=new URLSearchParams(r).toString();render()}if(el.id==='status'){state.status=el.value;const r=route();delete r.status;if(el.value)r.status=el.value;location.hash=new URLSearchParams(r).toString();render()}});
let searchTimer;document.addEventListener('input',event=>{if(event.target.id==='search'){const value=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.search=value;render();const el=$('#search');if(el){el.focus();el.setSelectionRange(value.length,value.length)}},220)}});
document.addEventListener('submit',async event=>{const f=event.target.closest('[data-form]');if(!f)return;event.preventDefault();try{prepareFormValues(f)}catch(error){f.querySelector('.error').textContent=error.message;return}const values=new FormData(f),body=Object.fromEntries(values);const submit=f.querySelector('button.primary');submit.disabled=true;f.querySelector('.error').textContent='';try{switch(f.dataset.form){case'attendance-flow':await submitAttendanceFlow(f,values);break;case'attendance':await submitAttendance(f,values);break;case'attendance-batch':await api('attendance/'+f.dataset.kind,{items:values.getAll('item').map(v=>JSON.parse(v))});break;case'business':await submitBusiness(f,values);break;case'login':await api('login',body);break;case'password':if(body.password!==body.confirm)throw new Error(L('兩次輸入的密碼不相同。','Passwords do not match.','ពាក្យសម្ងាត់ទាំងពីរមិនដូចគ្នា។'));delete body.confirm;await api('password',body);break;case'person':await api('people/update',{...body,id:f.dataset.id,revision:Number(f.dataset.revision),serviceProjects:values.getAll('serviceProjects')});break;case'record':if(f.dataset.id){const r=state.records.find(r=>r.id===f.dataset.id);await api('records/update',{...body,kind:r.kind,company:r.company,id:r.id,revision:Number(f.dataset.revision)})}else await api('records/create',{...body,company:f.elements.company.value,kind:f.dataset.kind});break;case'account':{const p=state.people.find(p=>p.id===body.employeeId);await api('accounts/create',{...body,scopes:body.role==='employee'?[p.companyCode]:values.getAll('scopes')});break}}if($('#dialog').open)$('#dialog').close();await refresh();flash(t('儲存成功'))}catch(error){f.querySelector('.error').textContent=error.message}finally{submit.disabled=false}});
window.addEventListener('hashchange',()=>{const r=route();if(r.company&&state.session?.companies.some(c=>c.code===r.company)){state.company=r.company}if(Object.hasOwn(r,'department')){state.search='';state.status=r.status||''}if($('#dialog').open)$('#dialog').close();render();window.scrollTo(0,0)});

const availableProjects=()=>state.config.projects.filter(p=>!state.company||p.company===state.company);
const optionKeys={tenant:'租客',managed_owner:'託管業主',self_or_agent_owner:'自用或自行委託房仲業主',local_transfer:'本地銀行轉帳',cash:'現金',rent_deduction:'從租金中扣除',overseas_remittance:'海外匯款',monthly:'月結',quarterly:'季結',semiannual:'半年結',annual:'年結',pending:'待核對（尚未調帳）',recorded:'已記錄（尚未對帳）',pending_review:'待財務確認（未計稅）'};
function optionLabel(v){return t(optionKeys[v]||v||'—')}
function selectField(label,name,options,value='',required=false,placeholder='請選擇'){
 return `<label>${t(label)}<select name="${name}" ${required?'required':''}><option value="">${t(placeholder)}</option>${options.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(t(text))}</option>`).join('')}</select></label>`;
}
function syncBillingFields(data={}){
 const f=$('#dialog form');if(!f)return;const project=state.config.projects.find(p=>p.id===f.elements.project.value),company=f.elements.company;
 if(project){if(!f.dataset.id)company.value=project.company;company.disabled=true}else company.disabled=!!f.dataset.id;
 const note=f.querySelector('[data-company-note]');if(note)note.textContent=project?`${t('出帳公司')}：${companyName(project.company)} · ${t('由項目自動帶入')}`:f.dataset.kind==='settlement'?t('請先選擇項目，系統會帶入出帳公司。'):t('一般業務可自行選擇公司。');
 const section=f.querySelector('[data-billing-fields]');if(!section){syncCompanyUI(f);return}
 section.innerHTML=project?selectField('收費對象','counterpartyType',Object.keys(project.fees).map(v=>[v,optionLabel(v)]),data.counterpartyType,true)+'<div class="form" data-fee-options></div>'+`<details class="receipt-box"><summary>${t('有轉錯帳戶？記錄收款核對資料')}</summary><div class="form section-gap">${selectField('實際收款公司','actualReceivingCompany',state.session.companies.map(c=>[c.code,companyName(c.code)]),data.actualReceivingCompany)}${input('應收帳戶備註','expectedAccount',data.expectedAccount,'maxlength="500"')}${input('實際入帳帳戶備註','actualAccount',data.actualAccount,'maxlength="500"')}<label class="check"><input type="checkbox" name="wrongAccount" ${data.wrongAccount?'checked':''}>${t('轉錯帳戶')}</label>${input('收款核對備註','reconciliationNote',data.reconciliationNote,'maxlength="500"')}<div class="help">${t('只記錄待核對事項，保留原出帳公司，不會自動調帳或移轉款項。')}</div></div></details>`:'';
 if(project)syncFeeOptions(data);syncCompanyUI(f);if(Object.keys(data).some(k=>['actualReceivingCompany','expectedAccount','actualAccount','wrongAccount','reconciliationNote'].includes(k)&&data[k])){const receipt=f.querySelector('.receipt-box');if(receipt)receipt.open=true}
}
function syncFeeOptions(data={}){
 const f=$('#dialog form'),project=state.config.projects.find(p=>p.id===f.elements.project.value),group=project?.fees[f.elements.counterpartyType.value],section=f.querySelector('[data-fee-options]');
 section.innerHTML=group?selectField('收費項目','feeItem',group.items.map(v=>[v,v]),data.feeItem,true)+selectField('收款方式','paymentMethod',group.methods.map(v=>[v,optionLabel(v)]),data.paymentMethod||(group.methods.length===1?group.methods[0]:''),true)+`<div class="help">${t('稅率待財務確認；此金額不會自動加稅或扣稅。')}</div>`:'';
}
function configSource(){return `<div class="footnote source">${t('設定來源')}：${esc(state.config.source||'—')} · ${esc(state.config.sourceDate||'')}<br>${t('已確認的是作業規則；實際交易仍需由經辦人建立。')}</div>`}
function billingRules(){
 return `<div class="notice info"><p>${t('建立應收款時，選項會依項目及收費對象自動調整。')}</p></div>`+availableProjects().map(p=>`<section class="card section-gap"><div class="card-title"><h2>${esc(p.name)}</h2><span class="badge">${t('出帳公司')}：${companyName(p.company)}</span></div>${Object.entries(p.fees).map(([key,v])=>`<div class="rule-group"><h3>${optionLabel(key)}</h3><div class="fee-tags">${v.items.map(item=>`<span class="badge">${esc(t(item))}</span>`).join('')}</div><p class="sub">${t('收款方式')}：${v.methods.map(optionLabel).join(' / ')}</p></div>`).join('')}</section>`).join('')+`<section class="card section-gap"><h2>${t('稅務資料待確認')}</h2><p class="sub">${t('以下是客戶提供的回覆，尚未作為自動計稅或扣繳依據。')}</p><ul class="rule-list">${(state.config.taxReview?.statements||[]).map(v=>`<li>${esc(t(v))}</li>`).join('')}</ul></section><section class="card section-gap"><h2>${t('審計資料需求')}</h2><div class="fee-tags">${(state.config.auditRequirements||[]).map(v=>`<span class="badge">${esc(t(v))}</span>`).join('')}</div><p class="sub">${t('已記錄需求；財務報表與固定資產模組尚未建置，不會顯示為已完成。')}</p></section>`+configSource();
}

initializeBusinessUI();
refresh();
